INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Produktionsfaktoren immer physische Ressourcen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch immaterielle Faktoren wie Wissen zählen"}, {"text": "Ja", "correct": false, "because": "Nicht nur physisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel der Nutzung von Produktionsfaktoren?', 3, '[{"text": "Effiziente Güterproduktion", "correct": true, "because": "Maximiert Output bei gegebenen Mitteln"}, {"text": "Maximale Lagerung", "correct": false, "because": "Nicht primär"}, {"text": "Manuelle Verteilung", "correct": false, "because": "Automatisierung oft besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche klassischen Produktionsfaktoren gibt es?', 5, '[{"text": "Arbeit", "correct": true, "because": "Menschliche Arbeitskraft"}, {"text": "Kapital", "correct": true, "because": "Maschinen und Finanzen"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Produktionsfaktor"}, {"text": "Musikwiedergabe", "correct": false, "because": "Irrelevant für Produktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Boden ist ein Produktionsfaktor. b) Produktionsfaktoren sind unbegrenzt verfügbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Ressourcen sind knapp"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Analyse von Produktionsfaktoren?', 4, '[{"text": "Verfügbarkeit", "correct": false, "because": "Bestimmt Einsatzmöglichkeiten"}, {"text": "Kosten", "correct": false, "because": "Beeinflussen Wirtschaftlichkeit"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein direkter Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Wissen als Produktionsfaktor gilt?', 2, '[{"text": "Ja", "correct": true, "because": "Wissen als immaterieller Faktor anerkannt"}, {"text": "Nein", "correct": false, "because": "Teil moderner Definitionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Produktionsfaktor ist für die IT-Branche besonders wichtig?', 3, '[{"text": "Wissen", "correct": true, "because": "Treibt Innovation und Entwicklung"}, {"text": "Rohstoffe", "correct": false, "because": "Weniger zentral"}, {"text": "Manuelle Arbeit", "correct": false, "because": "Automatisierung dominiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Verfügbarkeit von Produktionsfaktoren?', 5, '[{"text": "Technologischer Fortschritt", "correct": true, "because": "Verbessert Kapitalnutzung"}, {"text": "Bildung", "correct": true, "because": "Erhöht Arbeitsqualität"}, {"text": "Grafikdesign", "correct": false, "because": "Kein Produktionsfaktor"}, {"text": "Büroausstattung", "correct": false, "because": "Sekundär relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Kapital umfasst Maschinen. b) Produktionsfaktoren sind immer kostenlos. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Faktoren kosten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Analyse von Produktionsfaktoren?', 4, '[{"text": "Ressourcenknappheit", "correct": false, "because": "Bestimmt Einsatz"}, {"text": "Produktivität", "correct": false, "because": "Misst Effizienz"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Produktionsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Arbeit nur physische Tätigkeit?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst auch geistige Arbeit"}, {"text": "Ja", "correct": false, "because": "Geistige Arbeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Kapital in der Produktion?', 4, '[{"text": "Bereitstellung von Werkzeugen", "correct": true, "because": "Ermöglicht Produktion"}, {"text": "Finanzierung", "correct": true, "because": "Unterstützt Investitionen"}, {"text": "Kreative Gestaltung", "correct": false, "because": "Kein Kapitalmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Boden immer verfügbar ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Boden ist knapp und begrenzt"}, {"text": "Ja", "correct": false, "because": "Knappheit ist Realität"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung von Produktionsfaktoren?', 3, '[{"text": "Effizienz", "correct": true, "because": "Maximiert Output"}, {"text": "Maximale Nutzung", "correct": false, "because": "Knappheit beachten"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Wissen ist ein moderner Produktionsfaktor. b) Produktionsfaktoren sind unbegrenzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Knappheit gilt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Kombination von Produktionsfaktoren?', 5, '[{"text": "Hohe Produktivität", "correct": true, "because": "Optimiert Output"}, {"text": "Kosteneffizienz", "correct": true, "because": "Reduziert Aufwand"}, {"text": "Unbegrenzte Ressourcen", "correct": false, "because": "Ressourcen knapp"}, {"text": "Einheitliche Nutzung", "correct": false, "because": "Flexibilität nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Produktionsfaktoren unwichtig?', 3, '[{"text": "Verfügbarkeit", "correct": false, "because": "Bestimmt Einsatz"}, {"text": "Kombinierbarkeit", "correct": false, "because": "Fördert Effizienz"}, {"text": "Bildschirmauflösung", "correct": true, "because": "Kein Produktionsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Kapital nur finanzielle Mittel umfasst?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Maschinen und Anlagen"}, {"text": "Ja", "correct": false, "because": "Physisches Kapital zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Boden in der IT-Branche irrelevant?', 3, '[{"text": "Ja", "correct": true, "because": "Weniger relevant als Wissen"}, {"text": "Nein", "correct": false, "because": "Boden sekundär in IT"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu Produktionsfaktoren?', 4, '[{"text": "Softwareentwicklung", "correct": true, "because": "Nutzt Arbeit und Wissen"}, {"text": "Musikwiedergabe", "correct": false, "because": "Keine Produktion"}, {"text": "Bildbearbeitung", "correct": false, "because": "Sekundäre Tätigkeit"}]');
